# ABOUTME: Tests for filtering the generated healthcare fixtures down to the domain ontology.
# ABOUTME: Pure Python; the generic POLE+O base types and unused infrastructure labels are left out.

import pytest

from scripts.healthcare_fixtures import (
    EXCLUDED_LABELS,
    domain_entities,
    domain_relationships,
    domain_schema_statements,
    remove_excluded,
)

SCHEMA = """// Schema for Healthcare Context Graph
// Generated by create-context-graph

CREATE INDEX person_name IF NOT EXISTS FOR (n:Person) ON (n.name);

CREATE INDEX object_name IF NOT EXISTS FOR (n:Object) ON (n.name);

CREATE CONSTRAINT patient_patient_id_unique IF NOT EXISTS FOR (n:Patient) REQUIRE n.patient_id IS UNIQUE;
CREATE INDEX patient_name IF NOT EXISTS FOR (n:Patient) ON (n.name);

// Infrastructure: Document and Decision Trace indexes
CREATE INDEX document_title IF NOT EXISTS FOR (n:Document) ON (n.title);
CREATE CONSTRAINT decision_trace_id_unique IF NOT EXISTS FOR (n:DecisionTrace) REQUIRE n.id IS UNIQUE;

// Domain index after a comment
CREATE INDEX medication_name IF NOT EXISTS FOR (n:Medication) ON (n.name);
"""


@pytest.fixture(autouse=True)
def clean_test_data():
    """Override the conftest autouse fixture — the Neo4j test below sets up its own data."""
    yield


class TestExcludedLabels:
    def test_cover_the_pole_o_base_types_and_unused_infrastructure(self):
        # Arrange / Act / Assert
        assert EXCLUDED_LABELS == {"Person", "Organization", "Location", "Event", "Object", "Document", "DecisionTrace"}


class TestDomainEntities:
    def test_keeps_only_domain_labels(self):
        # Arrange
        entities = {"Person": [{"name": "Nurse James Morrison"}], "Patient": [{"name": "James Morrison"}],
                    "Object": [{"name": "Lab Results Summary"}], "Medication": [{"name": "Metformin 500mg"}]}

        # Act
        result = domain_entities(entities)

        # Assert
        assert list(result) == ["Patient", "Medication"]


class TestDomainRelationships:
    def test_drops_relationships_that_touch_an_excluded_label(self):
        # Arrange
        rels = [
            {"type": "WORKS_FOR", "source_label": "Person", "target_label": "Organization"},
            {"type": "TREATED_BY", "source_label": "Patient", "target_label": "Provider"},
            {"type": "LOCATED_AT", "source_label": "Facility", "target_label": "Location"},
        ]

        # Act
        result = domain_relationships(rels)

        # Assert
        assert [r["type"] for r in result] == ["TREATED_BY"]


SEEDED_FIXTURES = {"entities": {"Person": [{"name": "hf-test-seeded"}], "Object": [{"name": "hf-test-object"}],
                                "Patient": [{"name": "hf-test-patient"}]}}


class TestRemoveExcluded:
    def test_removes_only_what_earlier_seeds_created(self, neo4j_driver):
        # Arrange: seeded leftovers, plus a foreign Person node and index that are not ours
        neo4j_driver.execute_query("CREATE INDEX person_name IF NOT EXISTS FOR (n:Person) ON (n.name)")
        neo4j_driver.execute_query("CREATE INDEX hf_test_foreign IF NOT EXISTS FOR (n:Person) ON (n.hf_test)")
        neo4j_driver.execute_query(
            "CREATE (:Person {name: 'hf-test-seeded'}), (:Object {name: 'hf-test-object'}), "
            "(:Person {name: 'hf-test-foreign'}), (:Patient {name: 'hf-test-patient'})"
        )

        # Act
        try:
            remove_excluded(neo4j_driver, "neo4j", SEEDED_FIXTURES, SCHEMA)
            names = {r["n"] for r in neo4j_driver.execute_query(
                "MATCH (n) WHERE n.name STARTS WITH 'hf-test' RETURN n.name AS n").records}
            indexes = {r["name"] for r in neo4j_driver.execute_query(
                "SHOW INDEXES YIELD name WHERE name IN ['person_name', 'hf_test_foreign'] RETURN name").records}
        finally:
            neo4j_driver.execute_query("MATCH (n) WHERE n.name STARTS WITH 'hf-test' DETACH DELETE n")
            neo4j_driver.execute_query("DROP INDEX hf_test_foreign IF EXISTS")

        # Assert
        assert names == {"hf-test-foreign", "hf-test-patient"}
        assert indexes == {"hf_test_foreign"}


class TestDomainSchemaStatements:
    def test_keeps_domain_statements_and_drops_excluded_labels(self):
        # Arrange / Act
        statements = domain_schema_statements(SCHEMA)

        # Assert
        assert statements == [
            "CREATE CONSTRAINT patient_patient_id_unique IF NOT EXISTS FOR (n:Patient) REQUIRE n.patient_id IS UNIQUE",
            "CREATE INDEX patient_name IF NOT EXISTS FOR (n:Patient) ON (n.name)",
            "CREATE INDEX medication_name IF NOT EXISTS FOR (n:Medication) ON (n.name)",
        ]
